import{_ as t,o as a,c as s,a2 as l}from"./chunks/framework.BXzK3EA4.js";const o="/assets/8f5d498cae641a18.Cl9tsi0B.png",i="/assets/a3ed271112d4ae19.LIQ4QRJr.png",n="/assets/e562e566e345a73e.CBiMmHeq.png",r="/assets/e06371307983740d.D88wY0WU.png",p="/assets/dd63f46f7dfff985.By5PdN74.png",c="/assets/6aec45dc38ba91a3.ChHAm-yV.png",d="/assets/44f14741915f66c0.C2AOcuBG.png",m="/assets/f167f89578bdedd6.z_0HvocF.png",x=JSON.parse('{"title":"CentOS 7.x Firewall: Enable/Disable and Add Ports","description":"","frontmatter":{"title":"CentOS 7.x Firewall: Enable/Disable and Add Ports"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/centos-7-x-firewall-enable-disable-and-add-ports.md","filePath":"operations-knowledge-base/operating-system/linux/centos-7-x-firewall-enable-disable-and-add-ports.md","lastUpdated":1794316324000}'),f={name:"operations-knowledge-base/operating-system/linux/centos-7-x-firewall-enable-disable-and-add-ports.md"};function u(h,e,_,w,g,b){return a(),s("div",null,[...e[0]||(e[0]=[l('<p>In CentOS 7.x, the default firewall is firewalld. Here is an example using CentOS 7.6</p><p><img src="'+o+'" alt=""></p><ol><li>To check the firewall status, run the command: <code>sudo firewall-cmd --state</code></li></ol><p><img src="'+i+'" alt=""></p><p>If the firewall status shows &quot;not running,&quot; it means that the firewall is not enabled.</p><ol start="2"><li>To enable the firewall, you can use the following command: <code>systemctl start firewalld</code>.</li></ol><p><img src="'+n+'" alt=""></p><p>&quot;Running&quot; indicates that the firewall is currently active and running.</p><ol start="3"><li>disable the firewall, you can run the command: <code>systemctl stop firewalld.service</code>.</li></ol><p><img src="'+r+'" alt=""></p><ol start="4"><li><p>restart the firewall, you can run the command: <code>systemctl restart firewalld.service</code>.</p></li><li><p>To view all open ports in the firewall, you can use the command: <code>firewall-cmd --zone=public --list-ports </code>.</p></li></ol><p><img src="'+p+'" alt=""></p><p>As shown in the above image, only port 13360 is open, which is the remote port number.</p><ol start="6"><li>Open port</li></ol><p>firewall-cmd --zone=public --add-port=80/tcp --permanent # Open port 80</p><p><img src="'+c+'" alt=""></p><p>The return value &quot;success&quot; indicates that the port has been successfully opened.</p><ol start="7"><li>firewall-cmd --reload # Make the configuration take effect immediately.</li></ol><p><img src="'+d+'" alt=""></p><p>As shown in the above figure, please check all the open ports of the firewall. Port 80 is currently open.</p><ol start="8"><li>firewall-cmd --zone=public --remove-port=80/tcp --permanent  #Close port 80.</li></ol><p><img src="'+m+'" alt=""></p><ol start="9"><li>After closing port 80, check that port 80 is closed once the configuration takes effect.</li></ol>',23)])])}const A=t(f,[["render",u]]);export{x as __pageData,A as default};
